BEGIN;

-- Remove fabricated org_members data
DELETE FROM org_members;

-- Rename Demo Org to match real org (SRDLabs = MySQL org_id 3)
UPDATE organizations SET name = 'SRDLabs' WHERE id = 1;

-- Import additional organizations from MySQL (skip id=1 which already exists)
ON CONFLICT (id) DO NOTHING;

-- Ensure sequence is set correctly
SELECT setval('organizations_id_seq', (SELECT COALESCE(MAX(id), 1) FROM organizations));



-- ========================================
-- Table: organization_details
-- ========================================

DROP TABLE IF EXISTS organization_details CASCADE;

CREATE TABLE IF NOT EXISTS organization_details (
    org_id SERIAL PRIMARY KEY,
    org_name VARCHAR(50),
    status VARCHAR(10)
);


-- ========================================
-- Table: department_chart_details
